    public struct JointDef { public string name, parent; public Vector3 bindPos, restEuler;
        public JointDef(string n, string p, Vector3 b, Vector3 r) { name = n; parent = p; bindPos = b; restEuler = r; } }
    public struct PartDef { public string name, joint; public Kind kind; public float a, b, c, d; public string mat; public Vector3 pos, euler, scale;
        public PartDef(string n, string j, Kind k, float a, float b, float c, float d, string m, Vector3 p, Vector3 e, Vector3 s)
        { name = n; joint = j; kind = k; this.a = a; this.b = b; this.c = c; this.d = d; mat = m; pos = p; euler = e; scale = s; } }

